INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_FOLKLORE','Modern Urban Legend & Folklore (19th–20th c.)',1800,2000),
 ('PER_DIGITAL_FOLKLORE','Digital-Age Folklore & Vernacular Religion (21st c.)',2000,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_BURTON_STRANGE_RITES','secondary scholarship','Tara Isabella Burton, Strange Rites: New Religions for a Godless World (2020)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_HANEGRAAFF_NEWAGE','secondary scholarship','Wouter Hanegraaff, New Age Religion and Western Culture: Esotericism in the Mirror of Secular Thought (1996)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_VIRTUE_ANGELNUMBERS','primary text','Doreen Virtue, Angel Numbers (2005)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_BYRNE_SECRET','primary text','Rhonda Byrne, The Secret (2006)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_CAMPBELL_DIGITAL_RELIGION','secondary scholarship','Heidi Campbell (ed.), Digital Religion: Understanding Religious Practice in New Media Worlds (2013)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_HINE_MEME_MAGIC','secondary scholarship','Christopher Hine et al. / scholarship on meme magic, the Kek/Pepe egregore, and 4chan occulture (2016–2018)','Contemporary Folklore & Vernacular Religion'),
 ('SRC_PARTRIDGE_OCCULTURE','secondary scholarship','Christopher Partridge, The Re-Enchantment of the West, vols. 1–2 (2004–2005)','Contemporary Folklore & Vernacular Religion')
INSERT INTO _e VALUES
 ('ENT_VF_NEWAGE_ANGELS','New Age Guardian Angels','Angelic being','New Age angelic devotion','Contemporary Folklore & Vernacular Religion','[''personal guidance'', ''protection'', ''healing'', ''reassurance'']','B','Devotional engagement is documented and sincere: practitioners petition personal guardian angels by name, ask for signs, thank them, and seek their guidance through angel cards, automatic writing, and prayer. Codified in Doreen Virtue''s best-selling angel literature and angel oracle decks, and earlier in Hanegraaff''s account of New Age angelology. Distinct from the Christian doctrine: here every person has assignable, nameable angels reachable on demand, blended with reincarnation and the ''ascended masters.'' A real historical taproot is the Zoroastrian guardian-spirit complex (fravashis / amesha spentas), widely cited as ancestral to the Judeo-Christian guardian-angel idea, hence the reception_of edges to both the Christian and Zoroastrian anchors.'),
 ('ENT_VF_ANGEL_NUMBERS','Angel Numbers','Divinatory practice','New Age numerology / sign-reading','Contemporary Folklore & Vernacular Religion','[''divination'', ''guidance'', ''synchronicity'', ''reassurance'']','B','Sincere devotional/divinatory engagement: seeing repeating digits (111, 222, 444, 1111) is read as a direct message from one''s guardian angels; people pause, interpret the number''s meaning from published correspondences, and adjust action or take comfort accordingly. Codified by Doreen Virtue (Angel Numbers, 2005) within New Age numerology and exploded on Gen Z TikTok as a mass vernacular practice. A reading practice oriented toward the New Age angels, hence aligned_with them.'),
 ('ENT_VF_THE_UNIVERSE','The Universe','Personified abstraction','New Thought / Law of Attraction providence','Contemporary Folklore & Vernacular Religion','[''providence'', ''abundance'', ''fate'', ''answered desire'']','B','Genuinely petitioned, thanked, and trusted as a providential agent (''the Universe has my back,'' ''thank you, Universe,'' ''asking the Universe for X''). Functions as a quasi-deistic provider in Law-of-Attraction practice; Rhonda Byrne''s The Secret (2006) instructs the practitioner to ask the Universe, believe, and receive, treating it as a responsive personal force. Rooted in 19th-c. New Thought, hence Modern-Folklore period; the vernacular gratitude/petition idiom is ubiquitous online.'),
 ('ENT_VF_MANIFESTATION','Manifestation','Ritual category','Law of Attraction practice','Contemporary Folklore & Vernacular Religion','[''intention'', ''attraction'', ''desire'', ''ritual technique'']','B','A ritual/practice category with structured techniques (scripting, vision boards, affirmations, the 3-6-9 method, gratitude lists) directed at ''the Universe'' to obtain desired outcomes. Documented as a mass contemporary practice by Burton (Strange Rites) and rooted in New Thought via The Secret; the petitionary action is directed at and embodies trust in the Universe.'),
 ('ENT_VF_KEK','Kek (meme-magic egregore)','Egregore','internet meme-magic / chaos-magic egregore','Contemporary Folklore & Vernacular Religion','[''chaos'', ''chance'', ''manifestation through memes'', ''trolling'']','C','Documented sincere ritual engagement within a self-aware, half-ironic frame: 2016-era online communities consciously invoked ''Kek'' as an egregore, posted ''GET''/dubs as his confirmations, and read coincidences as his signs (chaos-magic ''meme magic''). The syncretism is explicit and conscious — adherents deliberately identified the meme-god with the ancient Egyptian frog-/darkness-god Kek, hence the reception_of edge to ENT_EGY_KEK. Contested/emergent and partly ironic, so conf C.'),
 ('ENT_VF_WITCHTOK','WitchTok / Online Neopagan Devotion','Movement','digital-age neopagan devotion','Contemporary Folklore & Vernacular Religion','[''deity worship'', ''witchcraft'', ''devotional practice'', ''divination'']','B','A digital devotional movement node: Gen Z devotees on TikTok/Instagram genuinely venerate ancient deities — building altars, leaving offerings, doing ''deity work,'' interpreting signs, and reporting being ''called'' by a god. Documented by Burton (Strange Rites) and digital-religion scholarship (Campbell). Wired reception_of to the specific ancient deities documented as WitchTok-popular; this models contemporary reception, not duplication, of those still-attested entities.'),
 ('ENT_VF_HIGHER_SELF','The Higher Self','Personified abstraction','New Age inner divinity','Contemporary Folklore & Vernacular Religion','[''inner divinity'', ''intuition'', ''guidance'', ''wholeness'']','B','Engaged devotionally as an inner divine source one petitions and takes guidance from (''connect with / align with your higher self,'' ''ask your higher self''). A central New Age construct (Hanegraaff) treated as the practitioner''s own divine guiding aspect, channeled and consulted; embodies the New Age self-as-divine premise. Widely practiced in meditation and manifestation circles.'),
 ('ENT_VF_STARSEEDS','Starseeds','Collective','UFO-religion identity','Contemporary Folklore & Vernacular Religion','[''cosmic origin'', ''spiritual mission'', ''awakening'', ''identity'']','C','A UFO-religion devotional identity: adherents believe their souls originated on other worlds (Pleiades, Sirius, Arcturus) and organize practice around ''activating'' their starseed mission, connecting with their star families, and reading galactic-origin signs. Documented within New Age/UFO-religion scholarship (Partridge, occulture); sincere identity-and-practice engagement, but emergent and contested, so conf C.'),
 ('ENT_VF_EGREGORE','Egregore','Personified abstraction','occult thoughtform concept','Contemporary Folklore & Vernacular Religion','[''thoughtform'', ''collective belief'', ''autonomous spirit'']','C','The general occult/chaos-magic concept of a collectively generated autonomous thoughtform that can be deliberately fed, invoked, and worked with. Practitioners genuinely create and engage egregores ritually (a sincere magical practice), making the concept the framework under which Kek is understood. Included as the conceptual hub for Kek; contested/theoretical, so conf C.');
