 ('ENT_VF_EGREGORE','PER_DIGITAL_FOLKLORE','The general occult/chaos-magic concept of a collectively generated autonomous thoughtform that can be deliberately fed, invoked, and worked with. Practitioners genuinely create and engage egregores ritually (a sincere magical practice), making the concept the framework under which Kek is understood. Included as the conceptual hub for Kek; contested/theoretical, so conf C.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_VF_NEWAGE_ANGELS','reception_of','ENT_CHR_GUARDIAN_ANGELS','high','New Age guardian angels are a direct contemporary reception of the Christian guardian-angel doctrine, reframed as personally assignable, nameable angels reachable on demand.'),
 ('ENT_VF_NEWAGE_ANGELS','reception_of','ENT_ZOR_FRAVASHIS','medium','The Zoroastrian fravashis (personal protecting spirits) are a documented historical taproot of the guardian-angel idea that New Age angelology inherits.'),
 ('ENT_VF_NEWAGE_ANGELS','reception_of','ENT_ZOR_AMESHA_SPENTAS','medium','The Zoroastrian Amesha Spentas (benevolent emanations/archangel prototypes) feed the angelic-hierarchy stream the New Age angels draw on.'),
 ('ENT_VF_ANGEL_NUMBERS','aligned_with','ENT_VF_NEWAGE_ANGELS','high','Angel numbers are read as direct messages from the New Age guardian angels; the practice is oriented toward those beings.'),
 ('ENT_VF_ANGEL_NUMBERS','member_of','ENT_VF_NEWAGE_ANGELS','medium','Angel numbers belong to the New Age angelic-devotion complex hubbed on the guardian angels.'),
 ('ENT_VF_MANIFESTATION','associated_with','ENT_VF_THE_UNIVERSE','high','Manifestation techniques are petitionary acts directed at the Universe to obtain desired outcomes.'),
 ('ENT_VF_MANIFESTATION','embodies','ENT_VF_THE_UNIVERSE','medium','Manifestation practice operationalizes and embodies trust in the providential Universe of Law of Attraction.'),
 ('ENT_VF_KEK','reception_of','ENT_EGY_KEK','high','The 2016 meme-magic Kek egregore is an explicit, conscious syncretism with the ancient Egyptian frog/darkness god Kek — a deliberate contemporary reception.'),
 ('ENT_VF_KEK','member_of','ENT_VF_EGREGORE','medium','Kek is the paradigmatic case of the egregore concept — a collectively generated, fed, and invoked thoughtform.'),
 ('ENT_VF_HIGHER_SELF','aligned_with','ENT_SPI_SPIRIT_GUIDES','medium','The higher self and spirit guides are adjacent New Age inner/helping guidance sources, frequently consulted together.'),
 ('ENT_VF_STARSEEDS','aligned_with','ENT_SPI_SPIRIT_GUIDES','low','Starseed practice draws on channeled star-family/guide communication characteristic of the spirit-guide complex.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_JM_LILITH','high','Lilith is among the most venerated figures in WitchTok deity work — a contemporary devotional reception of the existing entity.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_NOR_LOKI','high','Loki has a large, documented WitchTok/Lokean devotional following; modeled as contemporary reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_HECATE','high','Hecate is a flagship WitchTok deity for witchcraft and the crossroads; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_HADES','high','Hades is widely worked with in WitchTok/Hellenic-pagan deity work; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_PERSEPHONE','high','Persephone is one of the most popular WitchTok deities for transformation/underworld work; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_APHRODITE','high','Aphrodite is heavily venerated on WitchTok for love/self-worth devotion; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_HERMES','medium','Hermes has an active WitchTok following (luck, communication, travel); contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_DIONYSUS','medium','Dionysus is widely worked with on WitchTok for liberation/ecstasy devotion; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_NOR_FREYJA','medium','Freyja is a popular WitchTok/Norse-pagan deity for love, seidr, and witchcraft; contemporary devotional reception.'),
 ('ENT_VF_WITCHTOK','reception_of','ENT_CEL_BRIGID','medium','Brigid is widely venerated on WitchTok (and modern Druidry) for hearth, healing, and poetry; contemporary devotional reception.');
